      'документы в герметичной упаковке, наличные',
      'пауэрбанк — розеток в лагере нет'
    ]::text[];
  t3_safety_notes constant text[] := ARRAY[
      'Уровень сложности — выше среднего (со слов гида): альпинистских навыков и специальной подготовки не нужно, но общая физическая форма должна быть хорошей — тур рассчитан на людей, привыкших к длительным пешим нагрузкам. Дни 1 и 4 — длительные переезды без физической нагрузки; день 2 — умеренный: короткие прогулки по ровному и слегка пересечённому рельефу (шлак, застывшая лава).',
      'День 3 — сложный: продолжительный подъём на Плоский Толбачик, на высоту около 3000 метров по рыхлому вулканическому рельефу, перепад высот — более 1500 метров от лагеря. Подъём — до семи часов, спуск — ещё 3–4 часа.',
      'На высоте возможны ветер, холод и даже летний снег.',
      'Порядок экскурсий, переправа через реку Студёную и выход на восхождение определяются погодой, состоянием дорог и вулканической обстановкой; время возвращения и вершина не гарантируются — приоритет у безопасности группы.',
      'Противопоказания (со слов гида): тур активный — у участника не должно быть проблем с сердцем, дыханием и ногами (коленями).',
      'Людям с сердечно-сосудистыми заболеваниями и проблемами с суставами гид советует перед участием проконсультироваться с врачом.',
      'Возраст детей — по согласованию с гидом: он рассматривает каждый случай.'
    ]::text[];
  t4_what_to_bring constant text[] := ARRAY[
      'одежда слоями: термобельё или флис, тёплая куртка или пуховка — даже летом на озере и побережье холодно и ветрено',
      'водоотталкивающая куртка и брюки — от дождя и брызг на лодке',
      'резиновые сапоги или трекинговые ботинки с нескользящей подошвой — берега, тропы и броды могут быть мокрыми',
      'головной убор (тёплая шапка и кепка от солнца), солнцезащитные очки и крем — солнце на воде отражается сильно',
      'средство от насекомых — комары и мошка в тундре и у озера активны весь сезон',
      'купальник для термального бассейна в Паужетке и тапочки или сланцы для базы',
      'рюкзак 20–30 л для личных вещей в дневных выходах',
      'фотоаппарат или смартфон с запасным аккумулятором, в идеале — с длиннофокусным объективом: медведей снимают с расстояния',
      'личные лекарства и средства гигиены, небольшая аптечка — базовая аптечка есть у гида'
    ]::text[];
  t4_safety_notes constant text[] := ARRAY[
      'Уровень сложности — средний (со слов гида): специальная подготовка и опыт походов или джип-туров не нужны. Значительная часть маршрута — внедорожная дорога: броды, тундровые участки, переправы через реки; трясёт, в дороге — остановки для отдыха и фотографий.',
      'Пешие участки — по тропам заказника в сопровождении инспекторов, без длинных подъёмов, но по неровной местности: нужна закрытая удобная обувь.',
      'Лодочная экскурсия по озеру — в спасжилетах; при волне возможно покачивание.',
      'Встречи с дикими животными проходят в естественных условиях: появление медведей и сивучей, их количество и расстояние до них не гарантируются.',
      'На Курильском озере за медведями наблюдают с разрешённых мест, по правилам заказника и указаниям государственных инспекторов.',
      'Ограничений по здоровью на этот тур гид не ставит; экскурсия подходит участникам с обычной физической формой от 6 лет.'
    ]::text[];
  t5_what_to_bring constant text[] := ARRAY[
      'одежда по принципу многослойности: термобельё, флисовая кофта, тёплая куртка — вечера на юге Камчатки холодные даже летом',
      'ветро- и влагозащитная куртка и брюки — погода на побережье меняется быстро',
      'удобные трекинговые ботинки с нескользящей подошвой и запасная пара обуви на случай промокания',
      'головной убор, солнцезащитные очки и крем — на открытых участках солнце отражается от воды и скал',
      'купальник и полотенце — для термального бассейна и горячей реки',
      'репеллент от комаров и мошки',
      'фотоаппарат или смартфон с защитным чехлом, запасной аккумулятор и карта памяти',
      'небольшой рюкзак на день, личная аптечка, лекарства, которые принимаете постоянно',
      'документы в герметичной упаковке, небольшая сумма наличных'
    ]::text[];
  t5_safety_notes constant text[] := ARRAY[
      'Уровень сложности — средний (со слов гида): специальной спортивной подготовки не требуется, но это не полностью пассивный отдых — многочасовые переезды по бездорожью (в общей сложности 10–12 часов дороги за всю поездку), включая переправы через реки и броды.',
      'Пешие прогулки — по пересечённой местности (тундра, вулканические породы, фумарольные поля), 3–7 километров в день в спокойном темпе; пересадки на лодку и транспорт заказника, необорудованные тропы.',
      'Встречи с дикими животными проходят в естественных условиях: появление медведей и сивучей, их количество и расстояние до них не гарантируются.',
      'На Курильском озере за медведями наблюдают с разрешённых мест, по правилам заказника и указаниям государственных инспекторов.',
      'Программа может корректироваться в зависимости от погоды, уровня воды в реках и состояния дороги — безопасность участников в приоритете.',
      'Ограничений по здоровью на этот тур гид не ставит; путешествие подойдёт взрослым и детям от 6 лет при нормальной физической форме. Пожилым участникам и людям с ограниченной подвижностью нужно заранее предупредить гида — часть маршрута можно адаптировать.'
    ]::text[];
  t5_description_append constant text := ' Лучшим временем гид считает июль–сентябрь: на нерест идёт нерка, и медведи концентрируются у Курильского озера.';
BEGIN
  SELECT count(*) INTO v_n FROM partners WHERE slug = 'andrey-zaporozhets' AND category = 'guide';
  IF v_n <> 1 THEN
    RAISE WARNING '[1356] карточка гида andrey-zaporozhets не найдена (или не одна: %) — тексты гида 30.10 не внесены', v_n;
    RETURN;
  END IF;
  SELECT id INTO v_gid FROM partners WHERE slug = 'andrey-zaporozhets' AND category = 'guide';

  -- ── Горелый (zaporozhets-vulkan-gorelyy) ───────────────────────────
  UPDATE operator_tours SET title = t1_title, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(title) = '656873dc8a4a248be721c5fa868903d1';
  UPDATE operator_tours SET short_description = t1_short_description, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(short_description) = '0b344adf104cb62c7c4b252151d1fa45';
  UPDATE operator_tours SET description = t1_description, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(description) = 'efcf54d119ee89f47af069b98d4bd3fd';
  UPDATE operator_tours SET program = t1_program, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(program::text) = 'e0e151a7fe073c9f7e8c47d5f9f45406';
  UPDATE operator_tours SET included = t1_included, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(included, E'\n')) = 'f680421b25d497ec0172be381da62b93';
  UPDATE operator_tours SET what_to_bring = t1_what_to_bring, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND what_to_bring IS NULL;
  UPDATE operator_tours SET safety_notes = t1_safety_notes, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(safety_notes, E'\n')) = 'c54bd5128329dab6430b93d70f81708f';
  UPDATE operator_tours SET duration_hours = 12, updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND duration_hours = 12.50;
  UPDATE operator_tours SET price_note = replace(price_note,
           'посещение пещер входит в цену (со слов гида 29.10), описание пещер гид допишет сам.',
           'посещение пещер входит в цену (со слов гида 29.10). Трекинговые палки по прайсу гида входят в каждый тур, а в описании этого тура он советует взять их с собой — уточняйте при заявке.'), updated_at = NOW()
   WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL
     AND position('посещение пещер входит в цену (со слов гида 29.10), описание пещер гид допишет сам.' IN price_note) > 0;

  -- ── Опасный + Дачные (zaporozhets-kanyon-opasnyy-dachnye) ──────────
  UPDATE operator_tours SET program = t2_program, updated_at = NOW()
   WHERE slug = 'zaporozhets-kanyon-opasnyy-dachnye' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(program::text) = '488bb06cb113e979a2c834314c8c7f1b';
  UPDATE operator_tours SET what_to_bring = t2_what_to_bring, updated_at = NOW()
   WHERE slug = 'zaporozhets-kanyon-opasnyy-dachnye' AND operator_id = v_gid AND deleted_at IS NULL
     AND what_to_bring IS NULL;
  UPDATE operator_tours SET safety_notes = t2_safety_notes, updated_at = NOW()
   WHERE slug = 'zaporozhets-kanyon-opasnyy-dachnye' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(safety_notes, E'\n')) = '506e08cf78ebc8c949ae551e6e305fcb';
  UPDATE operator_tours SET weather_dependent = TRUE, updated_at = NOW()
   WHERE slug = 'zaporozhets-kanyon-opasnyy-dachnye' AND operator_id = v_gid AND deleted_at IS NULL
     AND weather_dependent IS NULL;
  UPDATE operator_tours SET price_note = price_note || ' Питание по прайсу гида входит в каждый тур, а в описании этого тура он советует взять с собой воду и лёгкий перекус — уточняйте при заявке.', updated_at = NOW()
   WHERE slug = 'zaporozhets-kanyon-opasnyy-dachnye' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(price_note) = 'a77dd85b3b7edbf1f7a6ee093520bcd8';

  -- ── Толбачик (zaporozhets-tolbachik-4-dnya) ────────────────────────
  UPDATE operator_tours SET program = t3_program, updated_at = NOW()
   WHERE slug = 'zaporozhets-tolbachik-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(program::text) = 'cf482970fc3bf001597e088b13a0e428';
  UPDATE operator_tours SET included = t3_included, updated_at = NOW()
   WHERE slug = 'zaporozhets-tolbachik-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(included, E'\n')) = '1e389bae20754661582232adddd1f27f';
  UPDATE operator_tours SET what_to_bring = t3_what_to_bring, updated_at = NOW()
   WHERE slug = 'zaporozhets-tolbachik-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND what_to_bring IS NULL;
  UPDATE operator_tours SET safety_notes = t3_safety_notes, updated_at = NOW()
   WHERE slug = 'zaporozhets-tolbachik-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(safety_notes, E'\n')) = '126529adc73b5425427a59d4a7e81c73';
  UPDATE operator_tours SET price_note = replace(price_note,
           ' Спальники программа не называет — уточняйте при заявке.',
           ' Спальник и коврик для ночёвок в палатках гид даёт в аренду (описание тура, 30.10); входит ли аренда в цену, он не написал — уточняйте при заявке.'), updated_at = NOW()
   WHERE slug = 'zaporozhets-tolbachik-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND position(' Спальники программа не называет — уточняйте при заявке.' IN price_note) > 0;

  -- ── Курильское 3 дня (zaporozhets-kurilskoe-ozero-3-dnya) ──────────
  UPDATE operator_tours SET what_to_bring = t4_what_to_bring, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-3-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND what_to_bring IS NULL;
  UPDATE operator_tours SET safety_notes = t4_safety_notes, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-3-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(safety_notes, E'\n')) = 'cd70f5cf3ece1b38733933774420f175';
  UPDATE operator_tours SET difficulty = 'medium', updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-3-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND difficulty = 'easy';

  -- ── Курильское 4 дня (zaporozhets-kurilskoe-ozero-4-dnya) ──────────
  UPDATE operator_tours SET what_to_bring = t5_what_to_bring, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND what_to_bring IS NULL;
  UPDATE operator_tours SET safety_notes = t5_safety_notes, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(array_to_string(safety_notes, E'\n')) = 'cd70f5cf3ece1b38733933774420f175';
  UPDATE operator_tours SET description = description || t5_description_append, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND md5(description) = 'eeea362997c14b2159a0a6f4905a4de3';
  UPDATE operator_tours SET difficulty = 'medium', updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND difficulty = 'easy';
  UPDATE operator_tours SET weather_dependent = TRUE, updated_at = NOW()
   WHERE slug = 'zaporozhets-kurilskoe-ozero-4-dnya' AND operator_id = v_gid AND deleted_at IS NULL
     AND weather_dependent IS NULL;

  -- ── Сверка: что не легло, называется вслух ─────────────────────────────
  IF NOT EXISTS (SELECT 1 FROM operator_tours WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL AND title = t1_title) THEN
    RAISE WARNING '[1356] тур zaporozhets-vulkan-gorelyy: поле title не обновлено — значение уже не то, что записали 1338/1342 (правил человек?), оставлено как есть';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM operator_tours WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL AND short_description = t1_short_description) THEN
    RAISE WARNING '[1356] тур zaporozhets-vulkan-gorelyy: поле short_description не обновлено — значение уже не то, что записали 1338/1342 (правил человек?), оставлено как есть';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM operator_tours WHERE slug = 'zaporozhets-vulkan-gorelyy' AND operator_id = v_gid AND deleted_at IS NULL AND description = t1_description) THEN
